"""Regenerate the offline editor's contract after changing the Python settings models."""

import json
from pathlib import Path

from application_filler.config import Settings


def main():
    target = Path(__file__).resolve().parents[1] / "config-editor" / "contract.js"
    contract = json.dumps(Settings.model_json_schema(), indent=2, ensure_ascii=False)
    defaults = json.dumps(Settings().model_dump(mode="json"), indent=2, ensure_ascii=False)
    target.write_text(
        "// Generated by scripts/update_config_editor_schema.py; do not edit by hand.\n"
        f"window.CONFIG_CONTRACT = {contract};\n"
        f"window.CONFIG_DEFAULTS = {defaults};\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
